#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 10000

int cmp(const void* a, const void* b) {
    return (*(char*) a) - (*(char*) b);
}

int main() {
    char s[MAX_SIZE];
    gets(s);

    int k;
    scanf("%d", &k);


    int n = strlen(s);

    char s_cp[n+1];
    strcpy(s_cp, s);

    qsort(s_cp, n, sizeof(char), cmp);

    if(k > n) {
        k = n;
    }

    char target = s_cp[k - 1];

    printf("%lld\n", strchr(s, target) - s);

    return 0;
}
